// Keep only jobs whose title or description mentions an AI / automation keyword.
const keywords = [
  "ai automation", "automation engineer", "n8n", "zapier", "make.com",
  "workflow", "rpa", "llm", "prompt engineer", "machine learning",
  "ai engineer", "integration engineer", "solutions engineer",
  "generative ai", "chatbot", "conversational ai"
];

return $input.all().filter(item => {
  const hay = ((item.json.title || "") + " " + (item.json.description || "")).toLowerCase();
  return keywords.some(k => hay.includes(k));
});

// Build one Gemini prompt per job. Keep all original job fields so we can use them later.
const job = $json;

const profile = "AI Automation Engineer. Stack: n8n, Supabase/PostgreSQL, FastAPI, Python, Twilio/WhatsApp API, Docker/nginx on Ubuntu VPS, LLM APIs (Gemini/OpenAI/Claude). Builds production WhatsApp commerce bots, event-ops systems and payment integrations. Open to remote work. Target roles: Automation Engineer, Solutions Engineer, Integration Engineer, AI Engineer.";

const prompt =
  "You are a strict technical recruiter. Score how well this job fits the candidate.\n\n" +
  "CANDIDATE PROFILE:\n" + profile + "\n\n" +
  "JOB:\n" +
  "Title: " + (job.title || "") + "\n" +
  "Company: " + ((job.company && job.company.display_name) || "") + "\n" +
  "Location: " + ((job.location && job.location.display_name) || "") + "\n" +
  "Description: " + (job.description || "") + "\n\n" +
  "Return ONLY minified JSON with these keys: match_score (integer 0-100), verdict (one of Strong, Medium, Weak), reason (max 20 words), remote (true or false). No markdown, no code fences, no extra text.";

return { json: Object.assign({}, job, { prompt: prompt }) };

// Read Gemini's answer, unwrap the JSON string inside it, and merge with the original job.
const job = $('Build Prompt').item.json;

let ai;
try {
  let raw = ($json.candidates
    && $json.candidates[0]
    && $json.candidates[0].content
    && $json.candidates[0].content.parts
    && $json.candidates[0].content.parts[0]
    && $json.candidates[0].content.parts[0].text) || "{}";
  // Strip accidental ```json fences if the model ever adds them.
  raw = raw.replace(/```json/gi, "").replace(/```/g, "").trim();
  ai = JSON.parse(raw);
} catch (e) {
  ai = { match_score: 0, verdict: "Weak", reason: "Could not parse AI response", remote: false };
}

const salary = job.salary_min
  ? ("\u00A3" + Math.round(job.salary_min) + " - \u00A3" + Math.round(job.salary_max || job.salary_min))
  : "Not listed";

return {
  json: {
    title: job.title || "",
    company: (job.company && job.company.display_name) || "",
    location: (job.location && job.location.display_name) || "",
    salary: salary,
    url: job.redirect_url || "",
    score: (typeof ai.match_score === "number") ? ai.match_score : parseInt(ai.match_score || 0, 10) || 0,
    verdict: ai.verdict || "Weak",
    reason: ai.reason || ""
  }
};
